    // 页面里点「检查更新」仍只检查；安装必须由确认动作触发。
    let updatePageVisited = false
    let selfUpdater = null
    if (SELF_UPDATE_ENABLED) {
      selfUpdater = createSelfUpdater({
        packageDir: PACKAGE_DIR,
        dataDir: UPDATE_DATA_DIR,
