      "content": "{\n  \"name\": \"dsh-chatgpt-sub\",\n  \"version\": \"0.6.5\",\n  \"description\": \"Sign in with your ChatGPT account to use ChatGPT models in DSH.\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"chatgpt\",\n    \"codex\",\n    \"subscription\",\n    \"oauth\",\n    \"plugin\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/songoao25/dsh-chatgpt-sub.git\"\n  },\n  \"homepage\": \"https://github.com/songoao25/dsh-chatgpt-sub\",\n  \"author\": \"SONGOAO25\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"locale/*.json\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"docs/INSTALL.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"prepublishOnly\": \"npm run build\",\n    \"test\": \"node tests/run-all.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": []\n    }\n  },\n  \"peerDependencies\": {\n    \"react\": \"^18.0.0\"\n  }\n}\n"
