      "path": "cordis.patch.yml",
      "content": "# dsh-chatgpt-sub bundle patch: mounts the plugin into a profile layer stack.\n# The row id is the key users override in their profile's cordis.patch.yml; the row name\n# is the module this package exports, so it must stay the package name.\n# Keep the two different: DSH's plugin card prints the row id and the module name on\n# separate lines (skipping one only when it equals the row title), so an id equal to the\n# module name renders the same string twice. Official bundles do the same, e.g.\n# 'agent-team' + '@deepseek-ai/dsh-experimental-agent-team'.\n- insert:\n    - id: chatgpt-subscription\n      name: 'dsh-chatgpt-sub'\n\n# This plugin owns only ChatGPT subscription OAuth binding, token upkeep, and the\n# openai-codex model route. It does NOT manage web search: the search provider\n# (searchProvider, e.g. deepseek-official / exa) is configured by the user in their\n# own profile layer, and this plugin never reads, rewrites, or switches search settings.\n"
    },
    {
      "path": "scripts/build.mjs",
      "content": "// dsh-chatgpt-sub — build script\n// 1) copy src/host.js -> lib/index.js（ESM host 插件）\n// 2) wrap src/client-bundle.js -> lib/client.js（client-modules 经典脚本 bundle）\n//    包装形态与官方 client 包一致：window.__ModuleLoader__.load({ id, factory })\n// 用法：node scripts/build.mjs（package.json build/prepack 均调用）\nimport { copyFile, mkdir, readFile, rm, writeFile } from 'node:fs/promises'\nimport { dirname, join } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { LOCALES } from '../src/locales.js'\nimport { createLanguageRuntime } from '../src/language-runtime.js'\n\nconst root = dirname(fileURLToPath(new URL('../package.json', import.meta.url)))\nconst libDir = join(root, 'lib')\n\nawait rm(libDir, { recursive: true, force: true })\nawait mkdir(libDir, { recursive: true })\n\nfor (const file of ['self-update.js', 'version.js']) await copyFile(join(root, 'src', file), join(libDir, file))\n\n// 1) host（ESM，原样复制，加文件头注释）\nawait writeFile(join(libDir, 'locales.js'), 'export const LOCALES = ' + JSON.stringify(LOCALES) + '\\n')\nconst hostSource = await readFile(join(root, 'src', 'host.js'), 'utf8')\nawait writeFile(join(libDir, 'index.js'), `// Generated by scripts/build.mjs from src/host.js — do not edit directly.\\n${hostSource}`)\n\n// 2) client（CJS 模块源 → __ModuleLoader__ bundle）\n// bundle id 必须等于包名（DSH 用它把 client bundle 和插件包对上），所以从 package.json\n// 现读，而不是写死——以后再改名只动 package.json 一处。\nconst pkg = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'))\nconst clientSource = (await readFile(join(root, 'src', 'client-bundle.js'), 'utf8'))\n  .replace('/*__LOCALES__*/{}', () => JSON.stringify(LOCALES))\n  .replace('/*__LANGUAGE_RUNTIME__*/', () => createLanguageRuntime.toString())\nconst wrapped = [\n  `window.__ModuleLoader__.load({ id: ${JSON.stringify(pkg.name)}, factory: (require) => {`,\n  'var module = { exports: {} }; var exports = module.exports;',\n  clientSource,\n  'return module.exports;',\n  '} });',\n  '',\n].join('\\n')\nawait writeFile(join(libDir, 'client.js'), wrapped)\n\nconsole.log('build OK → lib/index.js, lib/client.js')\n\nawait mkdir(join(root, 'locale'), { recursive: true })\nfor (const [language, dictionary] of Object.entries(LOCALES)) {\n  await writeFile(join(root, 'locale', language + '.json'), JSON.stringify({ meta: { title: dictionary['meta.title'], description: dictionary['meta.description'] } }, null, 2) + '\\n')\n}\n"
