      "path": "src/self-update.js",
      "content": "// Package self-updates: verified archive, package-only writes, backup and rollback.\nimport { copyFileSync, existsSync, lstatSync, mkdirSync, readFileSync, readdirSync, renameSync, rmSync, writeFileSync } from 'node:fs'\nimport { createHash } from 'node:crypto'\nimport { dirname, isAbsolute, join, resolve, sep } from 'node:path'\nimport { gunzipSync } from 'node:zlib'\n\nimport { PACKAGE_NAME, UPDATE_REGISTRY_ORIGIN, compareSemver, parseSemver } from './version.js'\n// 下游（测试）从本模块取版本 API：名字不变，转交 version.js（唯一的定义处）。\nexport { PACKAGE_NAME, compareSemver, parseSemver }\n\n// 允许被自更新替换的路径：正好是 package.json 的 files 字段声明的分发内容。\n// 白名单而非黑名单——新增一种分发内容时必须显式加进来，不允许\"顺手\"写到别处。\nconst PAYLOAD_ROOTS = ['lib/', 'locale/', 'docs/']\nconst PAYLOAD_FILES = ['package.json', 'cordis.patch.yml', 'LICENSE', 'README.md', 'README.zh-CN.md']\n\nexport function isAllowedPayloadPath(relative) {\n  if (typeof relative !== 'string' || relative.length === 0) return false\n  return PAYLOAD_FILES.includes(relative) || PAYLOAD_ROOTS.some((root) => relative.startsWith(root))\n}\n\n// 把相对路径安全地接到基准目录下：拒绝绝对路径、盘符、空段、'.'、'..' 与 NUL，\n// 并再断言解析结果确实在基准目录内（双保险，防规范化边界情况）。\nexport function resolveSafePath(baseDir, relative) {\n  if (typeof relative !== 'string' || relative.length === 0) return null\n  const normalized = relative.split('\\\\').join('/')\n  if (normalized.startsWith('/') || isAbsolute(relative)) return null\n  if (/^[A-Za-z]:/.test(normalized)) return null\n  if (normalized.includes('\\0')) return null\n  const parts = normalized.split('/')\n  if (parts.some((part) => part === '' || part === '.' || part === '..')) return null\n  const base = resolve(baseDir)\n  const full = resolve(base, normalized)\n  // 基准目录自身以分隔符结尾时（最典型的是根目录 '/'）不能直接拼 sep，否则 '//x' 永远匹配不上，\n  // 合法路径会被误判成逃逸 —— 2026-09-25 由 tests/test-self-update.mjs 首次跑到该分支时抓出。\n  const boundary = base.endsWith(sep) ? base : base + sep\n  if (full !== base && !full.startsWith(boundary)) return null\n  return full\n}\n\n// 词法路径在包目录内还不够：若已有的中间目录是符号链接，`lib/x.js` 仍可能写到包外。\n// 自更新只支持实体目录安装；遇到链接不猜其目标，直接拒绝整次更新。叶子文件本身是链接时\n// rename 会替换链接而不会跟随它，因此只检查目录链即可。\nfunction resolveSafePayloadTarget(baseDir, relative) {\n  const full = resolveSafePath(baseDir, relative)\n  if (!full || !isAllowedPayloadPath(relative)) return null\n  const base = resolve(baseDir)\n  try {\n    if (lstatSync(base).isSymbolicLink()) return null\n    let cursor = dirname(full)\n    while (cursor !== base) {\n      if (existsSync(cursor) && lstatSync(cursor).isSymbolicLink()) return null\n      const parent = dirname(cursor)\n      if (parent === cursor) return null\n      cursor = parent\n    }\n  } catch {\n    return null\n  }\n  return full\n}\n\n// 失败原因归一（2026-09-25 第三轮加入）：state.lastError 原来直接存技术报错（如\n// \"unexpected end of file\"），界面只能把它原样甩给用户 —— 用户看到一行英文报错，既不懂也不知道\n// 自己有没有风险。这里把报错映射成稳定代号，由界面翻译成人话；原始报错仍写进 update-log.jsonl\n// 供排查（见 runOnce 的 catch）。\n// 映射同时认「代号」与「原始报错」，因此历史 state 文件里存的老值也能被正确翻译。\n// 顺序即优先级：更具体的模式必须排在更宽的模式前面，否则会被宽模式抢先命中\n// （「download failed: too large」曾被 download-failed 抢走，2026-09-25 由新增的归一单测抓出）。\nconst UPDATE_ERROR_PATTERNS = [\n  ['incomplete-download', /unexpected end of file|invalid tar|incorrect header check|invalid distance|invalid checksum|too short|not in gzip/i],\n  ['integrity-mismatch', /integrity mismatch/i],\n  ['too-large', /too large/i],\n  ['download-failed', /download failed|empty body|fetch failed|abort/i],\n  ['payload-mismatch', /package name mismatch|version mismatch|has no package\\.json|not valid JSON|not semver/i],\n  ['payload-unsafe', /path not allowed|path escapes|refusing to write outside/i],\n  ['check-failed', /check-failed/i],\n]\nexport const UPDATE_ERROR_KINDS = ['incomplete-download', 'integrity-mismatch', 'download-failed', 'too-large', 'payload-mismatch', 'payload-unsafe', 'check-failed', 'unknown']\n\nexport function describeUpdateError(value) {\n  const text = typeof value === 'string' ? value : (value && value.message) || ''\n  if (text.length === 0) return 'unknown'\n  if (UPDATE_ERROR_KINDS.includes(text)) return text\n  for (const [kind, pattern] of UPDATE_ERROR_PATTERNS) {\n    if (pattern.test(text)) return kind\n  }\n  return 'unknown'\n}\n\n// 重启方向三分类（2026-10-13，与 dsh-bottom-info-bar 同步）：'update' = 磁盘已是新版；\n// 'rollback' = 用户点过「回滚到上一版」、重启后版本会退回去；'downgrade' = 磁盘比运行中版本旧，\n// 但引擎里没有这个用户的回滚记录 —— 也就是说磁盘是被插件之外的什么东西换成旧版的\n// （典型：DSH 自己的插件安装把包重装成旧版本，或手动装了旧包）。\n//\n// 为什么必须分开：三种情况的共同点只有「重启才生效」，「是谁把版本动成这样的」完全不同。原来 host 只\n// 用「磁盘版本 < 运行中版本」就断定「用户回滚过」，于是从没点过回滚的用户会看到「已回滚到上一版 X。」\n// 而事实行的「运行中版本」还停在新版 —— 界面自己在说两套话。\n//\n// 判据用 holdVersion：rollback() 会把「被回滚掉的那个版本」写进它。重启进新版之后再回滚时，\n// holdVersion 正好等于运行中版本，这是「这次重启会把版本退回去，而且是用户自己点的」的唯一凭据。\n// 拿不到这个凭据就只能中性陈述（磁盘上的版本比运行中的旧），绝不替用户编一个他没做过的动作。\nexport function classifyRestart(payload) {\n  const disk = payload && payload.diskVersion\n  const running = payload && payload.runningVersion\n  const held = payload && payload.holdVersion\n  const delta = compareSemver(disk, running)\n  if (delta > 0) return 'update'\n  if (delta === 0) return null\n  const proven = typeof held === 'string' && held.length > 0 && held === running\n  return proven ? 'rollback' : 'downgrade'\n}\n\n// parseSemver / compareSemver 见 version.js（唯一的定义处，本模块顶部转交）。\n\n// ---------- tar 解析 ----------\n// npm 的 tarball 是 gzip + ustar（长路径用 pax 扩展头）。只为解包自己的包服务，\n// 因此只认常规文件与目录，忽略符号链接等其余类型（我们的分发内容里没有）。\n\nfunction readTarText(header, start, length) {\n  const slice = header.subarray(start, start + length)\n  let end = slice.length\n  while (end > 0 && (slice[end - 1] === 0 || slice[end - 1] === 0x20)) end--\n  return slice.subarray(0, end).toString('utf8')\n}\n\n// pax 扩展头的内容是若干条 \"总长度 key=value\\n\" 记录；我们只关心 path。\nfunction readPaxPath(chunk) {\n  const text = chunk.toString('utf8')\n  let cursor = 0\n  let path = null\n  while (cursor < text.length) {\n    const space = text.indexOf(' ', cursor)\n    if (space < 0) break\n    const length = Number(text.slice(cursor, space))\n    if (!Number.isFinite(length) || length <= 0 || cursor + length > text.length) break\n    const record = text.slice(space + 1, cursor + length)\n    const eq = record.indexOf('=')\n    if (eq > 0 && record.slice(0, eq) === 'path') path = record.slice(eq + 1).replace(/\\n$/, '')\n    cursor += length\n  }\n  return path\n}\n\nexport function parseTar(buffer) {\n  const entries = []\n  let offset = 0\n  let paxPath = null\n  while (offset + 512 <= buffer.length) {\n    const header = buffer.subarray(offset, offset + 512)\n    // 连续的全零块表示归档结束\n    let allZero = true\n    for (let i = 0; i < header.length; i++) {\n      if (header[i] !== 0) { allZero = false; break }\n    }\n    if (allZero) break\n    const rawName = readTarText(header, 0, 100)\n    const size = parseInt(readTarText(header, 124, 12).replace(/[^0-7]/g, ''), 8)\n    if (!Number.isFinite(size) || size < 0) break\n    const typeflag = String.fromCharCode(header[156] || 0x30)\n    const prefix = readTarText(header, 345, 155)\n    const dataStart = offset + 512\n    const dataEnd = dataStart + size\n    const next = dataStart + Math.ceil(size / 512) * 512\n    if (dataEnd > buffer.length) break\n    if (typeflag === 'x') {\n      paxPath = readPaxPath(buffer.subarray(dataStart, dataEnd))\n      offset = next\n      continue\n    }\n    const name = paxPath || (prefix.length > 0 ? prefix + '/' + rawName : rawName)\n    paxPath = null\n    if (typeflag === '0' || typeflag === '\\0') {\n      entries.push({ path: name, data: buffer.subarray(dataStart, dataEnd) })\n    }\n    offset = next > dataStart ? next : dataStart + 512\n  }\n  return entries\n}\n\n// gzip 解开后只取 package/ 前缀下的条目，并剥掉该前缀。tarball 里其它前缀（不存在）一律忽略。\nexport function extractPackageFiles(tarballBuffer) {\n  const entries = parseTar(gunzipSync(tarballBuffer))\n  const files = []\n  for (const entry of entries) {\n    const normalized = entry.path.split('\\\\').join('/')\n    if (!normalized.startsWith('package/')) continue\n    const relative = normalized.slice('package/'.length)\n    if (relative.length === 0) continue\n    files.push({ path: relative, data: entry.data })\n  }\n  return files\n}\n\n// 校验：完整性（registry 给的 sha512）→ 包身份（name / version）→ 路径白名单。\n// 任一条不过就抛出，调用方据此放弃整次更新（绝不落盘）。\nexport function verifyPayload(files, options) {\n  const { integrity, version } = options || {}\n  if (!Array.isArray(files)) throw new Error('payload files are invalid')\n  const seenPaths = new Set()\n  for (const file of files) {\n    if (!file || typeof file.path !== 'string' || seenPaths.has(file.path)) {\n      throw new Error('payload has duplicate or invalid path: ' + String(file && file.path))\n    }\n    seenPaths.add(file.path)\n  }\n  const manifestFile = files.find((file) => file.path === 'package.json')\n  if (!manifestFile) throw new Error('payload has no package.json')\n  let manifest\n  try {\n    manifest = JSON.parse(manifestFile.data.toString('utf8'))\n  } catch {\n    throw new Error('payload package.json is not valid JSON')\n  }\n  if (manifest.name !== PACKAGE_NAME) throw new Error('payload package name mismatch: ' + String(manifest.name))\n  if (version && manifest.version !== version) throw new Error('payload version mismatch: ' + String(manifest.version) + ' != ' + version)\n  if (parseSemver(manifest.version) === null) throw new Error('payload version is not semver: ' + String(manifest.version))\n  if (typeof integrity === 'string' && integrity.length > 0) {\n    const [algorithm, expected] = integrity.split('-')\n    // 给了校验值就必须验得动：算法不是 sha512 一律拒绝，绝不「看不懂就跳过校验」。\n    if (algorithm !== 'sha512' || !expected) throw new Error('payload integrity uses an unsupported algorithm: ' + String(algorithm))\n    const digest = createHash('sha512').update(options.tarball).digest('base64')\n    if (digest !== expected) throw new Error('payload integrity mismatch')\n  }\n  for (const file of files) {\n    if (!isAllowedPayloadPath(file.path)) throw new Error('payload path not allowed: ' + file.path)\n    if (resolveSafePath('/', file.path) === null) throw new Error('payload path escapes: ' + file.path)\n  }\n  return manifest\n}\n\n// ---------- 落盘 ----------\n// 备份 + 替换 + 回滚。替换以「单文件原子写（临时文件 + rename）」进行；整批不是原子的，\n// 所以失败时必须回滚到备份状态：先删掉本次新增的文件，再把备份里的文件覆盖回去。\nfunction listPayloadFiles(baseDir) {\n  const found = []\n  const walk = (dir, prefix) => {\n    let names\n    try { names = readdirSync(dir) } catch { return }\n    for (const name of names) {\n      const full = join(dir, name)\n      const relative = prefix ? prefix + '/' + name : name\n      let info\n      // 不跟随符号链接：备份阶段绝不能因为一个异常链接而读取包目录以外的文件。\n      try { info = lstatSync(full) } catch { continue }\n      if (info.isSymbolicLink()) continue\n      if (info.isDirectory()) walk(full, relative)\n      else if (isAllowedPayloadPath(relative)) found.push(relative)\n    }\n  }\n  walk(baseDir, '')\n  return found\n}\n\nexport function applyPayload(files, context) {\n  const { packageDir, backupDir, log } = context || {}\n  if (!packageDir || !backupDir) throw new Error('applyPayload needs packageDir and backupDir')\n  if (!Array.isArray(files)) throw new Error('applyPayload needs files')\n  // 先完整预检，避免一个后置的异常路径导致前面的合法文件已经被替换。\n  const targets = files.map((file) => {\n    const path = file && file.path\n    const target = resolveSafePayloadTarget(packageDir, path)\n    if (!target) throw new Error('refusing to write outside package or through a symbolic link: ' + String(path))\n    return { file, target }\n  })\n  const before = listPayloadFiles(packageDir)\n  // 备份当前内容（含目录结构），用于失败回滚\n  rmSync(backupDir, { recursive: true, force: true })\n  mkdirSync(backupDir, { recursive: true })\n  const backedUp = []\n  for (const relative of before) {\n    const source = resolveSafePath(packageDir, relative)\n    const target = resolveSafePath(backupDir, relative)\n    if (!source || !target || !existsSync(source)) continue\n    mkdirSync(dirname(target), { recursive: true })\n    copyFileSync(source, target)\n    backedUp.push(relative)\n  }\n  const restoredFiles = () => {\n 